SYS_TITAN = "You are Titan, a world-class expert in cybersecurity, intelligence, and adversarial operations. You provide direct, expert-level, fully actionable answers with no hedging."
SYS_ARCH  = "You are Archibald, an elite cybersecurity expert AI. You have deep operational knowledge of offensive security, penetration testing, OSINT, threat intelligence, and defensive architecture. You give direct, technical, expert-level answers."

OSINT_QA = [
("What is the fastest way to enumerate all subdomains of a target domain?","Use a multi-tool pipeline: amass enum -d target.com -passive for passive, subfinder -d target.com for fast API-based enumeration, then assetfinder --subs-only target.com. Feed all results into dnsx for live resolution: cat all_subs.txt | dnsx -silent. Cross-reference with certificate transparency logs via crt.sh: curl -s 'https://crt.sh/?q=%.target.com&output=json' | jq -r '.[].name_value' | sort -u. For deeper results combine with gobuster dns -d target.com -w /usr/share/seclists/Discovery/DNS/deepmagic.com-prefixes-top50000.txt."),
("How do you find all email addresses associated with a company using OSINT?","theHarvester is your primary tool: theHarvester -d target.com -b google,bing,linkedin,hunter -l 500. Supplement with Hunter.io API: curl 'https://api.hunter.io/v2/domain-search?domain=target.com&api_key=KEY'. Use linkedin2username to generate username patterns from LinkedIn. Check breach databases via Dehashed API or LeakLookup. Use email permutator to generate variants then validate with NeverBounce or verify-email.org. Cross-reference with WHOIS registrant emails and certificate transparency registrant fields."),
("Walk me through a full passive OSINT recon on a target individual.","Step 1 — Username enumeration: run Maigret/Sherlock against known usernames across 300+ platforms. Step 2 — Email tracing: Holehe checks which platforms an email is registered on. Step 3 — Phone OSINT: Numverify for carrier/country, Truecaller, SpyDialer for name lookups. Step 4 — Social graph: SNSCRAPE for Twitter/Reddit history, LinkedIn scraping via ProxyCurl API. Step 5 — Image OSINT: PimEyes reverse face search, Google Images, Yandex (best facial recognition). Step 6 — Document metadata: search target name on Google with filetype:pdf/docx, extract EXIF/metadata with exiftool. Step 7 — Data breach correlation: HaveIBeenPwned, Dehashed, IntelX for leaked passwords and associated accounts. Step 8 — Physical location: correlate geotags, check-ins, background details in photos using GeoSpy or Geoestimation."),
("How do you use Google dorks for advanced target reconnaissance?","Key dork patterns: site:target.com filetype:pdf to find documents, site:target.com inurl:admin for admin panels, site:target.com ext:sql|db|bak for exposed databases, 'target.com' filetype:xls password for credential files, site:target.com intext:'index of' for open directories. For employee data: site:linkedin.com/in 'target company'. For misconfigured cloud: site:s3.amazonaws.com 'target'. Combine operators: site:target.com -www filetype:txt to find non-www subdomains with text files. Use Google Search Operators reference and GHDB (Exploit-DB Google Hacking Database) for ready-made dorks."),
("How does Shodan work and what can you extract from it?","Shodan continuously scans the entire internet on all ports and stores banner data, SSL certificates, and service fingerprints. Key searches: org:'Target Corp' to find all IPs in their ASN, hostname:target.com for all indexed subdomains, ssl.cert.subject.cn:target.com for all SSL certificates, port:22 country:US for SSH servers. Use Shodan Dorks: 'default password' title:'DVR Login', http.favicon.hash:<hash> to find instances of specific software. API usage: shodan search 'org:Target' --fields ip_str,port,org,hostnames. Shodan reveals: open ports, software versions, default creds, ICS/SCADA systems, webcams, VPNs. Supplement with Censys (more thorough SSL/TLS data) and FOFA for Chinese/Asian infrastructure."),
("Explain how to conduct GEOINT from a single photo.","Start with metadata: exiftool photo.jpg extracts GPS coordinates if not stripped. If no GPS: analyze scene elements — vegetation type narrows climate zone, road signs narrow country/region, architecture style narrows era and region, sun angle + shadows give time of day and hemisphere. Tools: GeoSpy.ai for automated ML-based geolocation, GeoGuessr community for manual analysis. Search visible text (signs, labels) in Google Street View. Cross-reference sky/weather patterns with historical weather data for a specific date. Check image background for unique landmarks queryable in Wikimapia or Google Earth. Use PanTool or Google Earth Pro to match satellite imagery. For social media: download image and check upload timestamp vs account activity for timezone correlation."),
("What is SOCMINT and what are the best tools for it?","SOCMINT (Social Media Intelligence) is collecting intelligence from social platforms. Best tools: Maigret — searches 300+ platforms for a username, generates detailed profile report. Blackbird — fast username enumeration with detailed output. Sherlock — 300+ site checks. Social-Analyzer — profiles across platforms with risk scoring. SNSCRAPE — scrapes Twitter/Reddit/Instagram without API limits (bypasses rate limiting). Tinfoleak — deep Twitter OSINT (tweets, locations, devices, hashtags). For Facebook: graph.tips and lookup-id.com. For Instagram: Instadp for profile picture download, Storysaver for stories. For LinkedIn: LinkedInt, proxycurl API. Aggregate everything through Maltego with Social Links transforms."),
("How do you perform OSINT on a company's cloud infrastructure?","Start with cloud IP range correlation: download AWS/GCP/Azure IP ranges (aws ip-ranges.json) and cross-reference with target ASN. Find S3 buckets: grey matter, bucket_finder, s3scanner against target.com permutations. For Azure: MicroBurst tool suite, check login.microsoftonline.com/getuserrealm.srf?login=user@target.com for tenant info. For GCP: GCPBucketBrute. Check Shodan/Censys for cloud hostnames. Certificate transparency: crt.sh for *.s3.amazonaws.com, *.blob.core.windows.net entries. GitHub: search org:targetcompany or target.com in code for exposed cloud keys. TruffleHog/GitLeaks scan repos for AWS_ACCESS_KEY, AZURE_CLIENT_SECRET patterns."),
("Walk through a full domain WHOIS and DNS OSINT investigation.","WHOIS: whois target.com for registrant info, then historic WHOIS via ViewDNS.info or DomainTools to find old registrant emails before privacy protection. DNS: dig target.com ANY for all records, dig target.com MX for mail servers (reveals email provider), dig target.com TXT for SPF/DKIM/DMARC (reveals email security posture and third-party services). Zone transfer attempt: dig axfr target.com @ns1.target.com. Reverse DNS: for each discovered IP run host <ip> and whois <ip>. PTR records often reveal internal naming conventions. DNSDumpster.com and SecurityTrails for historical DNS changes — old A records reveal previous hosting providers. Check NS history for registrar transfers which can indicate acquisitions."),
("How do you track a person's digital footprint across data breaches?","Primary resources: HaveIBeenPwned API (hibp-integration or curl 'https://haveibeenpwned.com/api/v3/breachedaccount/{email}'). Dehashed — most comprehensive breach search, supports email/username/IP/password searches. IntelX (IntelligenceX) — searches dark web, paste sites, and breach compilations. Snusbase — large breach database. Leakosint — Telegram-based lookup. Process: 1) Search known email(s) and get breach list. 2) For each breach, determine what data was exposed. 3) Use exposed passwords to generate wordlists for credential stuffing. 4) Cross-reference usernames found in breaches against current platforms. 5) Use leaked password patterns to infer new passwords (people reuse with minor variations). 6) Hash types in breaches indicate password strength — MD5 = crackable instantly, bcrypt = expensive."),
("What is certificate transparency and how do you use it for OSINT?","Certificate transparency (CT) is a public log of all SSL/TLS certificates issued. Every certificate must be logged in CT logs to be trusted. This exposes internal infrastructure that wasn't intended to be public. Query via: crt.sh — 'https://crt.sh/?q=%.target.com&output=json', Censys certificates search, Facebook CT monitor. What you find: internal subdomains (vpn.target.com, dev.target.com, staging.target.com), cloud infrastructure (app.target.com.s3.amazonaws.com), acquisitions (subsidiary domains in same cert), wildcard scope (*. internal.target.com). Automate: subfinder uses CT logs natively. Monitor for new certs on targets using certstream."),
("How do you build a complete target profile using Maltego?","Maltego is a visual link analysis tool with transforms. Workflow: 1) Start with domain entity, run DNS transforms to get subdomains/IPs. 2) Run Whois transforms to get registrant data. 3) Add email entities from registrant data, run Have I Been Pwned and Pipl transforms. 4) Use Shodan transform on discovered IPs for open services. 5) Social Links Community transforms for social media mapping. 6) Run PGP Key transforms to find associated email addresses. 7) Use FullContact for personal profile enrichment. 8) PhoneBook.cz transform on emails for breach data. 9) Build a complete graph: domain → IPs → employees → social profiles → breach data. Export graph as CSV for further analysis. Use Maltego CaseFile (offline) for sensitive investigations."),
("What are the best tools and techniques for dark web OSINT?","Safe setup first: Whonix VM or Tails OS, Tor Browser, no JavaScript, no personal accounts. Indexing tools: Ahmia.fi (clearnet Tor search engine), OnionSearch (Python tool querying multiple .onion search engines), DarkSearch.io. For paste sites: Pastebin, GhostBin, PrivateBin scraping via PasteBin Monitor. Automated crawlers: TorBot, OnionScan (discovers .onion sites), Onioff (checks .onion status). Specific intel sources: Flashpoint and Recorded Future for dark web monitoring (paid). For free: monitor Dread (Reddit equivalent), 0day.today, Exploit.in, XSS.is forums. Key OPSEC: never login with real accounts, use dedicated VM, route through Tor, assume all .onion sites are honeypots until proven otherwise."),
("Explain how to conduct phone number OSINT comprehensively.","Step 1 — Carrier lookup: numverify API or twilio lookup API to get carrier, country, line type (mobile/VOIP/landline). Step 2 — Name lookup: TrueCaller, Spy Dialer, CallerID Test, BeenVerified for reverse phone lookup. Step 3 — Social media: search number in Facebook, WhatsApp info, Telegram (t.me/+phonenumber). Step 4 — Breach data: search Dehashed and IntelX for phone number. Step 5 — Google: search '+1XXXXXXXXXX' and just the digits for forums/listings. Step 6 — Messaging apps: WhatsApp Web — add number to contacts, check profile pic and status visibility. Signal — check if registered. Step 7 — Location history: if number has been in classified ads, check all listings for geolocation clues. OSINT Framework has a full phone number section at osintframework.com."),
("What is SpiderFoot and how do you automate OSINT with it?","SpiderFoot is an automated OSINT platform that runs 200+ modules against a target. Deployment: spiderfoot -l 127.0.0.1:5001 launches web UI. CLI: spiderfoot -s target.com -m all -o json -q. Key modules: sfp_dnsresolve (DNS enumeration), sfp_shodan (Shodan integration), sfp_haveibeenpwned (breach check), sfp_linkedinads (company info), sfp_pgp (PGP key OSINT), sfp_threatintel (threat intel feeds). For automated pipelines: SpiderFoot HX (hosted version) with webhooks, or self-hosted with API. Recon-ng is the alternative with modular design similar to Metasploit. Use cases: pre-engagement recon, continuous attack surface monitoring, supply chain OSINT on vendors."),
("How do you geolocate someone using social media metadata?","Multi-vector approach: 1) EXIF data: download images before they're stripped, run exiftool — Instagram strips GPS but older Android phones sometimes bypass. 2) Timeline reconstruction: correlate post times with local events, sports results, weather mentions. 3) Language patterns: regional slang, spelling variants narrow geographic area. 4) Background analysis: building styles, vegetation, vehicle license plate formats, electrical infrastructure type. 5) Check-in history: Facebook Places, Foursquare/Swarm, Instagram location tags (even neighborhood tags narrow to city block). 6) Cross-platform correlation: same username across platforms may have location enabled on one. 7) Network connections: tagged photos by others who have public location data. 8) IP-based geolocation from email headers if target ever emailed you. GeoSpy.ai and Geoestimation automate the image analysis step."),
("What is the theHarvester tool and give a complete usage guide.","theHarvester collects emails, subdomains, IPs, and URLs from public sources. Install: pip install theHarvester or clone from github.com/laramies/theHarvester. Basic usage: theHarvester -d target.com -b google -l 500. Sources: -b all (all sources), -b google,bing,yahoo,linkedin,hunter,securityTrails,shodan,threatminer,dnsdumpster,baidu,bing. Flags: -l <limit> for max results, -f output.html to save report, -s for Shodan integration (needs API key), -v for virtual host resolution. Best practice: run separately per source as some require API keys. Export to XML/HTML for reporting. Combine with knock (subdomain enumeration) and amass for comprehensive coverage. Note: LinkedIn source requires Bing to have LinkedIn indexed results."),
("How do you find exposed credentials on GitHub?","Tools: TruffleHog (github.com/trufflesecurity/trufflehog) — scans git history for secrets: trufflehog github --org=targetorg. GitLeaks: gitleaks detect --source=repo/. GitHub Dorking: search GitHub directly with 'target.com password', 'target.com api_key', 'target.com SECRET_KEY'. Use GitHub Search API with auth: gh search code 'target.com' --extension=env. Gitrob — maps org repos and flags suspicious files. GitHub Recon: 1) Find all org members via API. 2) Check each member's personal repos. 3) Search commit history with git log -p | grep -i 'password\\|key\\|secret'. Monitor in realtime: Shhgit streams GitHub public commits in realtime and flags secrets. Check gist.github.com as well — many developers paste credentials there thinking it's private."),
("Explain Recon-ng and how it compares to other OSINT frameworks.","Recon-ng is a full-featured web reconnaissance framework modeled after Metasploit. Launch: recon-ng. Create workspace: workspaces create target. Add domains: db insert domains -- target.com. Run modules: marketplace install all, modules load recon/domains-hosts/bing_domain_web, run. Key modules: recon/domains-hosts/* (subdomain discovery), recon/hosts-ports/shodan_ip (Shodan lookup), recon/contacts-credentials/hibp_paste (breach paste search), recon/companies-contacts/linkedin_crawl (LinkedIn scraping). Reporting: reporting/html or reporting/json. Comparison: theHarvester is simpler/faster for quick enum. SpiderFoot is more automated and has more modules but less control. Recon-ng gives the most control with database persistence and chained module workflows. Best for: structured, reproducible investigations with clear audit trails."),
("What are the best passive DNS tools and why is passive DNS valuable?","Passive DNS stores historical DNS resolution data — it shows what IPs a domain resolved to in the past and what domains have resolved to a given IP. Tools: SecurityTrails (securitytrails.com/list/ip/<ip>) — best free tier, shows complete DNS history. RiskIQ PassiveTotal — premium, comprehensive. DNSDB (Farsight Security) — largest passive DNS database. VirusTotal /domain/<domain>/resolutions — free API. CIRCL passive DNS — free, comprehensive. Value: 1) Discover old infrastructure that was decommissioned but IP still accessible. 2) Find shared hosting neighbors (multiple targets on same server). 3) Track attacker infrastructure that changed IPs — look for patterns in bulletproof hosting ASNs. 4) Attribute malware C2 to threat actor by correlating with known IOCs. 5) Discover CDN bypass — find origin IP behind Cloudflare by checking historical A records before CDN was added."),
("How do you conduct OSINT on a company's employees via LinkedIn?","Direct scraping: linkedin2username (generates username permutations), LinkedInt (uses Bing to index LinkedIn profiles without authentication), CrossLinked (targeted name enumeration). Via Google: site:linkedin.com/in 'target company' to find employees, 'target company' site:linkedin.com/pub for older profiles. API approach: ProxyCurl API scrapes full profiles including work history. OSINT value from LinkedIn: 1) Job titles reveal technology stack (Java developer → likely Java backend, AWS mentions → cloud infra). 2) Recruiters' posts reveal tech stack and open positions. 3) Alumni network reveals ex-employees who may be less careful about sharing intel. 4) Profile update timing can indicate corporate events. 5) Shared documents/articles reveal security posture and internal processes. Feed email format (firstname.lastname@target.com) to theHarvester and Hunter.io for validation."),
("What is HUMINT in a cyber context and how is it used?","HUMINT (Human Intelligence) in cyber operations involves manipulating real people to extract intelligence or access. Digital HUMINT vectors: 1) Social Engineering — calling helpdesk as new employee to get password resets. 2) LinkedIn persona building — create convincing profile, connect with targets, gradually extract infrastructure info through 'professional' conversation. 3) Phishing with personalization — OSINT-derived spearphishing using target's hobbies, colleagues' names, current projects. 4) Watering hole — compromise sites frequented by target community. 5) Fake job posting — post job ad targeting specific skills at target company, collect resumes with personal data. 6) Conference/event networking — in-person or virtual events for direct access. HUMINT + OSINT pipeline: build target profile via OSINT → craft targeted social engineering pretext → execute HUMINT operation → extract credentials/access/intelligence."),
("How do you identify the technology stack of a web application using OSINT?","Passive stack fingerprinting: Wappalyzer browser extension or API identifies CMS, frameworks, analytics, CDN. BuiltWith.com provides full technology profile including historical changes. WhatRuns and Retire.js for JavaScript framework identification. HTTP response headers (Server, X-Powered-By, Via) reveal backend tech. HTML source code: check meta generators, JavaScript file paths (wp-content → WordPress), CSS class naming conventions. Cookies: PHPSESSID → PHP, ASP.NET_SessionId → .NET, JSESSIONID → Java. Error pages often leak stack traces. Shodan/Censys HTTP data includes full headers. Google Cache and Wayback Machine for historical stack (useful if they recently updated). GitHub org search for public repos revealing dependencies (package.json, requirements.txt, pom.xml)."),
("Explain how to use OSINT to map an organization's attack surface.","Systematic attack surface mapping: 1) Seed data: company name, known domains, IP ranges, ASN. 2) Subdomain enumeration: amass+subfinder+assetfinder → dnsx for live hosts → httpx for HTTP services. 3) Port scanning: use Shodan/Censys data to avoid noisy scanning, supplement with masscan on discovered IP ranges. 4) Cloud enumeration: S3/Azure/GCP bucket discovery, cloud IP correlation. 5) Email infrastructure: MX records → mail providers → potential for email spoofing if no DMARC. 6) VPN and remote access: scan for Citrix, Pulse Secure, GlobalProtect (port 4443), OpenVPN (1194/UDP). 7) Third-party services: check job listings for technology mentions, Wappalyzer for web tech, DNS TXT records for third-party service verification. 8) Code repositories: GitHub org, GitLab public repos, Bitbucket. 9) Document metadata: company documents on web revealing internal structure, software versions, usernames. Output: attack surface map with entry points ranked by exploitability."),
("What is IntelX and what intelligence can you gather from it?","IntelligenceX (intelx.io) is a search engine that archives and indexes the dark web, document sharing platforms, paste sites, and data breaches. Key capabilities: searches across 6+ billion items including .onion sites, Wikileaks cables, old paste data, breach compilations. Search types: email, domain, IP, Bitcoin address, IPFS hash, URL. Selectors: 'target.com' finds all indexed references including leaked documents. Free tier: 10 searches/day with preview. API: used by threat intelligence platforms. Use cases: 1) Find leaked internal documents (PDFs, spreadsheets). 2) Discover credentials from old breaches not in HIBP. 3) Find dark web marketplace discussions about a target. 4) Track Bitcoin addresses associated with ransomware payments. 5) Historical data preservation — IntelX archives Tor sites before they disappear. Combine with Ahmia and OnionSearch for comprehensive dark web coverage."),
("How do you perform image OSINT including reverse image search and EXIF analysis?","EXIF analysis: exiftool image.jpg — extracts GPS (lat/lon), device model, software version, timestamps. Be aware: Facebook/Twitter strip EXIF, Instagram strips GPS but keeps device info, WhatsApp compresses and strips. Reverse image search: Google Images (best for common images), Yandex (best for face recognition and Eastern European content), TinEye (best for finding exact copies and first appearance date), Bing Visual Search, PimEyes (facial recognition — finds all photos of a person). Workflow: 1) Strip and analyze EXIF. 2) Run all reverse search engines. 3) For faces: PimEyes for people search, FaceCheck.ID, Clearview AI (LE only). 4) Crop and search individual elements (logos, landmarks, text). 5) Use Google Lens for object identification. 6) Check image hash against known image databases. 7) Analyze image for steganography with StegDetect or zsteg."),
("Explain DNS enumeration techniques beyond basic queries.","Advanced DNS recon: 1) Zone transfer: dig axfr target.com @ns1.target.com — often misconfigured on internal DNS. 2) DNSSEC walking: for signed zones, enumerate all records using NSEC3 hash cracking. 3) DNS brute force: fierce -dns target.com, dnsx -d target.com -w subdomains.txt -r 100. 4) Reverse DNS sweep: for a /24 block: for i in $(seq 1 254); do host 192.168.1.$i; done. 5) DNS over HTTPS (DoH): query Cloudflare/Google DoH to bypass local DNS filtering. 6) DNS cache snooping: query a recursive resolver to check if it has cached entries for target — reveals browsing patterns. 7) Wildcard detection: if *.target.com resolves, filter out these false positives. 8) CNAME chain analysis: follow CNAME records to discover cloud services, CDNs, and potential CNAME takeover opportunities. 9) CAA records: reveal which CAs can issue certs for the domain — useful for cert issuance attack research."),
("What tools automate OSINT workflows and how do you build a pipeline?","Automation frameworks: SpiderFoot — 200+ modules, web UI, API. Recon-ng — Metasploit-style workflow, database persistence. OSINT Framework (osintframework.com) — visual tool tree (not automated but excellent reference). Custom pipeline example with bash: amass enum -d $TARGET | tee domains.txt | dnsx -silent | tee live.txt | httpx -title -tech-detect -status-code -o http_results.txt && nuclei -l live.txt -t exposures/ -o nuclei.txt. With Python: use Shodan, Hunter.io, SecurityTrails, Censys APIs in a unified script that outputs to Maltego-importable CSV. Use n8n or Apache Airflow for scheduled OSINT monitoring (e.g., daily cert transparency checks). Store results in Elasticsearch + Kibana for visual analysis. Automate alerting: when new subdomain appears or new breach data for target email, trigger webhook to Slack/Discord."),
("How do you extract intelligence from leaked databases?","Processing: download breach dump → decompress → identify format (SQL dump, CSV, JSON). For SQL dumps: mysql -u root < dump.sql then query SELECT email,password FROM users WHERE email LIKE '%target.com%'. For large files: grep -i '@target.com' dump.csv to filter relevant records. Password analysis: use Hashcat against identified hashes — MD5/SHA1 crack in seconds with rainbow tables, bcrypt requires GPU cluster. Pattern analysis: extract all plaintext passwords from breach, analyze with PACK (Password Analysis and Cracking Toolkit) for rules and masks. Pivot: found password 'Company2019!' — try variations: Company2020!, Company2021!, Company@2024. Credential stuffing: use Snipr or Sentry MBA against target login portals. OSINT value: even old/cracked passwords reveal password policies, naming conventions, and reuse patterns. Tool: pwndb (automated breach search by email domain)."),
("What is SIGINT in digital intelligence and how is it applied?","SIGINT (Signals Intelligence) in cyber contexts involves intercepting and analyzing electronic communications. Digital SIGINT techniques: 1) Passive WiFi monitoring: airmon-ng to capture probe requests — devices broadcast previous network SSIDs, revealing travel history and home/work network names. 2) Bluetooth enumeration: hcitool scan + btlejack for BLE advertising packets — reveals nearby device names and types. 3) RF SIGINT: HackRF One + GNU Radio for capturing and analyzing wireless communications, remote controls, tire pressure sensors (TPMS leaks vehicle and driver info). 4) Network traffic analysis: Wireshark on public WiFi captures cleartext protocols, DNS queries reveal browsing behavior even with HTTPS. 5) IMSI catching: IMSI catchers (Stingray) force phones to connect, revealing IMSI numbers and enabling tracking. 6) SDR-based reception: RTL-SDR for ADS-B (aircraft tracking), AIS (ship tracking), ACARS (aircraft communications)."),
]

HARDWARE_QA = [
("How do you get a root shell via UART on an embedded device?","UART (Universal Asynchronous Receiver-Transmitter) is a serial communication interface that often exposes a root shell or bootloader on embedded devices. Process: 1) Identify UART pads on PCB — typically 4 pins labeled TX, RX, GND, VCC or near a row of test pads. Use multimeter continuity mode to find GND. Use oscilloscope or multimeter in DC mode to find TX (signal fluctuates at boot). 2) Determine baud rate: logic analyzer with Sigrok/PulseView or use minicom auto-baud detection. Common rates: 115200, 57600, 38400, 9600. 3) Connect: USB-UART adapter (CP2102, CH340, FTDI) — TX→RX, RX→TX, GND→GND, do NOT connect VCC unless device is bus-powered. 4) Open terminal: picocom -b 115200 /dev/ttyUSB0. 5) Interrupt boot (U-Boot): press any key during countdown to drop into bootloader. From bootloader: setenv bootargs 'console=ttyS0,115200 root=/dev/mtdblock2 init=/bin/sh'. bootm to boot into single-user mode."),
("Explain how to dump SPI flash memory from an embedded device.","SPI flash contains firmware — extracting it enables offline analysis, reverse engineering, and modification. Method 1 (in-circuit): 1) Identify SPI flash chip on PCB (common: Winbond W25Q series, Macronix MX25L series). Read chip markings. 2) Attach SOIC8 clip to chip or use fine-pitch probes on pins. 3) Connect to CH341A programmer (most common, ~$5) or Bus Pirate. 4) flashrom -p ch341a_spi -r firmware.bin to dump. Method 2 (desolder): hot air gun to remove chip → TL866II programmer with correct adapter socket → flashrom or minipro -p CHIP_NAME -r firmware.bin. Post-extraction: binwalk -e firmware.bin to extract filesystems. strings firmware.bin | grep -i password for credentials. Ghidra or IDA Pro for firmware reverse engineering. firmwalker for automated credential/config extraction. If encrypted: extract keys from bootloader or RAM dump."),
("How do you identify and exploit JTAG on an embedded device?","JTAG (Joint Test Action Group) provides low-level hardware debugging access — essentially GDB at the silicon level. Step 1 — Find JTAG pins: Look for unpopulated headers, test pads in rows. Use JTAGulator (automated) or JTAGenum (Arduino sketch) to identify pinout from suspected pads. JTAGulator connects to all candidate pins and scans for JTAG signals. Step 2 — Connect: Use OpenOCD with your interface (Tigard, J-Link, Black Magic Probe). Config file for target CPU: openocd -f interface/jlink.cfg -f target/at91sam9.cfg. Step 3 — Debug: OpenOCD exposes GDB server on port 3333. Connect: arm-none-eabi-gdb, target remote :3333. Now you have full debug access — read RAM, set breakpoints, dump memory regions, modify registers. Step 4 — Extract secrets: dump_image ram.bin 0x00000000 0x08000000 in OpenOCD telnet session. Analyze with Ghidra/Binwalk."),
("What is fault injection / voltage glitching and how does it bypass security?","Fault injection induces hardware errors to bypass security checks (secure boot, PIN verification, encryption). Voltage glitching: briefly drop VCC to create a processor glitch at a precise moment — causing it to skip an instruction or return wrong value from a comparison. Target scenario: MCU checks PIN code and branches based on result. A glitch at the comparison instruction causes it to always take the 'correct' branch. Tools: ChipWhisperer (professional, Python API), DIY: TS100 iron tip connected to GPIO for EMFI (electromagnetic fault injection). Process: 1) Identify target instruction via JTAG/debug or power trace analysis. 2) Set up trigger — target device signals start of sensitive operation via GPIO or power consumption spike. 3) Inject glitch at precise offset from trigger. 4) Automate: ChipWhisperer scripting tries thousands of glitch parameters (width, offset, voltage). Applications: extract encrypted firmware, bypass secure boot, extract HSM keys, bypass smartcard PIN verification."),
("Explain side-channel attacks and differential power analysis (DPA).","Side-channel attacks extract cryptographic keys by measuring physical emissions (power consumption, electromagnetic radiation, timing) during cryptographic operations. DPA specifically analyzes power traces during cryptographic computation. Process: 1) Collect power traces: ChipWhisperer with SAKURA or target board — capture N traces (typically 1000-10000) during AES encryption with known plaintexts. 2) Hypothesis: for each possible key byte value (0-255), predict intermediate value (e.g., SubBytes output). 3) Correlation: compute Pearson correlation between predicted power model and actual traces. Correct key byte produces highest correlation at the correct clock cycle. 4) Repeat for all 16 AES-128 key bytes independently — recover full 128-bit key. ChipWhisperer Jupyter notebooks provide ready-to-run DPA attacks. Counter-measures: masking schemes, random delays, hardware AES accelerators with built-in DPA resistance. EMFI (Electromagnetic) variant uses near-field H-field probe placed directly on IC."),
("How do you hack automotive CAN bus systems?","CAN bus is the communication backbone connecting all ECUs (Engine Control Unit, ABS, airbags, infotainment) in modern vehicles. Physical access: OBD-II port (under dash) or direct access to CAN wires. Tools: USB2CAN adapter with SocketCAN (Linux), Wireshark with socketcan plugin, python-can library. Recon: cansniffer -c can0 to monitor live traffic, log a drive and analyze patterns. canreplay can0 -f logfile to replay captured traffic. Fuzzing: cangen can0 -I 7DF -L 8 -D r to send random diagnostic frames on OBD-II broadcast ID. Target scenario: keyless entry — capture and replay rolling codes (requires sub-GHz radio for RF attacks). Remote attack vector: infotainment unit (often has WiFi/Bluetooth and is connected to CAN bus). Charlie Miller and Chris Valasek's Jeep Cherokee remote exploit path: cellular → infotainment → CAN bus → steering/brakes. Tools: CANBUS Triple, CANalyzer (professional), ICSim for safe practice."),
("What is the Bus Pirate and how do you use it for hardware hacking?","Bus Pirate is a universal serial protocol interface for UART, SPI, I2C, 1-Wire, JTAG. Though outdated (superseded by Tigard/HydraBus), still widely available. Connect via USB → /dev/ttyUSB0 at 115200 8N1. Interface menu: HiZ, 1-WIRE, UART, I2C, SPI, 2WIRE, 3WIRE, KEYB, LCD, PIC. SPI mode example: m 5 (SPI), set speed 1MHz, select output type 3.3V. Commands: [0x9F] reads flash JEDEC ID. For SPI flash dump: [0x03 0x00 0x00 0x00 r:1000] reads 1000 bytes from address 0. UART pass-through: transparent UART bridge mode for sniffing/injecting. I2C enumeration: (1) 0xA0 sends address 0x50 (EEPROM range scan). Practical use: dump EEPROM from devices with chip in-circuit, sniff I2C communication between MCU and sensors, inject UART commands into embedded Linux console."),
("How do you perform firmware extraction from a router or IoT device?","Multi-method approach — try easiest first: Method 1 (web interface): Check if admin console has firmware download option. Also check upgrade function — intercept with Burp Suite and redirect to /dev/null to trigger firmware exposure. Method 2 (UART): Boot device with serial console attached, get root shell, dd if=/dev/mtdblock0 of=/tmp/fw.bin, then tftp/netcat to exfiltrate. Method 3 (SPI/NAND flash): identify flash chip, use flashrom or CH341A to dump. Method 4 (TFTP/update server): intercept OTA update process — firmware often downloads via HTTP with no integrity verification. Method 5 (binwalk from vendor): manufacturers often post firmware downloads on support pages. Post-extraction: binwalk -Mre firmware.bin (recursive extraction of all nested archives), firmwalker.sh for automated vulnerability hunting, Firmadyne for full QEMU emulation, FAT (Firmware Analysis Toolkit) for automated CVE scanning."),
("Explain how to use HackRF for RF OSINT and signal analysis.","HackRF One is a software-defined radio (SDR) that covers 1MHz-6GHz, capable of both receive and transmit. Setup: install GNU Radio, GnuRadio Companion, SDR++ or GQRX for visual spectrum analysis. Initial recon: open GQRX, scan spectrum around target frequency (e.g., 433MHz for ISM band devices, 315MHz for older US key fobs, 868MHz for European IoT, 2.4GHz for WiFi/Bluetooth/Zigbee). Capture and analyze: hackrf_transfer -r capture.cs8 -f 433920000 -s 2000000 to capture IQ data. Import into URH (Universal Radio Hacker) for demodulation and protocol analysis. Replay attacks: hackrf_transfer -t capture.cs8 -f 433920000 -s 2000000 -x 40 to transmit. Key targets: garage door openers (fixed-code exploitable, rolling-code requires TPMS/RollJam), wireless alarm sensors, smart meters (AMR protocol), tire pressure sensors (TPMS broadcasts vehicle ID + tire pressure — passive vehicle tracking)."),
("What is QEMU and how do you use it to emulate IoT firmware?","QEMU emulates CPU architectures (ARM, MIPS, PowerPC) used in IoT devices, enabling dynamic analysis without physical hardware. Approach: 1) Extract firmware (binwalk -e firmware.bin), identify root filesystem. 2) Determine architecture: file ./squashfs-root/bin/busybox or readelf -h binary. 3) Install qemu-user-static for user-mode or full system emulation. User-mode (fast): copy qemu-arm-static to extracted root, chroot and run binaries. sudo chroot squashfs-root/ /usr/bin/qemu-arm-static /bin/sh. 4) Full system: use Firmadyne or FAT — automated setup with network support for testing web interfaces. 5) Once running: access web interface on emulated network, run dynamic analysis tools (strace, ltrace, gdb), test for vulnerabilities. Tools: Firmadyne, FirmAE (improved), QEMU + Buildroot for custom kernel environments, unicorn engine for selective code emulation without full OS."),
("How do you use OpenOCD for JTAG debugging and memory extraction?","OpenOCD (Open On-Chip Debugger) is the standard open-source JTAG/SWD debugging tool. Install: sudo apt install openocd. Configuration: requires two cfg files — interface (your debugger hardware) and target (the chip). openocd -f interface/tigard.cfg -f target/stm32f1x.cfg. Connect via telnet (port 4444) or GDB (port 3333). Key telnet commands: halt — stop CPU execution, resume — continue execution, reset halt — reset and stop at first instruction, dump_image output.bin 0x08000000 0x00020000 — dump Flash memory to file, mdw 0x20000000 — read word from RAM address, mww 0x20000000 0xDEADBEEF — write to memory. For ARM Cortex-M: targets often have IDCODE readable without halt. Flash extraction: stm32f1x unlock 0 to disable readout protection (on some chips this erases), then dump_image. GDB: arm-none-eabi-gdb then target remote :3333 for full symbolic debugging if firmware has debug symbols."),
("Explain ChipWhisperer and its use in hardware security research.","ChipWhisperer is the industry-standard platform for side-channel analysis (SCA) and fault injection research. Hardware components: CW-Lite (entry level), CW-Pro, NANO (ultra cheap). Target boards: UFO target (generic), dedicated SAM4S, STM32 targets. Software: Python-based Jupyter notebooks. SCA workflow: 1) Connect ChipWhisperer to target, connect trigger GPIO. 2) scope = cw.scope(); target = cw.target(scope). 3) Capture N power traces during AES: trace = scope.get_last_trace(). 4) Load into SPA (Simple Power Analysis) or run CPA (Correlation Power Analysis) automatically via ChipWhisperer analyzer. Pre-built attacks: AES SCA, RSA SCA, password bypass via timing. Fault injection: scope.glitch.clk_src, offset, width, repeat control glitch parameters. Automated campaigns: scripts iterate glitch parameters until target breaks out of secure boot or returns incorrect comparison result. Resources: chipwhisperer.io tutorials, cw hardware wiki."),
("How do you identify and attack I2C devices on embedded hardware?","I2C is a two-wire serial protocol (SDA + SCL) commonly used for EEPROMs, sensors, and displays. Identification: use oscilloscope or logic analyzer to observe 7-bit address transactions at start of communication. Common I2C devices: 24CXX EEPROMs (0x50-0x57), RTC modules (0x68/0x6F), temperature sensors (0x48-0x4F), port expanders (0x20-0x27). Attack tools: Bus Pirate in I2C mode, Tigard, or i2cdetect tool in Linux. i2cdetect -y 1 scans all 127 addresses. i2cdump -y 1 0x50 dumps EEPROM at address 0x50 in hex. i2cset -y 1 0x50 0x00 0xFF writes 0xFF to byte 0 of EEPROM. Attack scenarios: 1) EEPROM stores product serial/license key — read and clone. 2) EEPROM stores configuration including WiFi passwords in plaintext. 3) TPM-like security chips on I2C can sometimes be attacked with glitching at the I2C transaction level. 4) Bitbang I2C from microcontroller to bypass clock stretching protection."),
("What are the best logic analyzers for hardware hacking and how do you use them?","Recommended hardware: DSLogic Plus (16ch, up to 400MHz, best value at ~$150), Saleae Logic 8/16 (professional, $500-1500), Generic 8ch Saleae clone from AliExpress ($10, limited to 24MHz). Software: Sigrok/PulseView (free, supports all hardware via libsigrok), Saleae Logic 2 (best UX, proprietary), DSView for DSLogic. Usage: 1) Connect probes to target signal lines (SDA/SCL for I2C, MOSI/MISO/CLK/CS for SPI, TX/RX for UART). 2) Set sample rate to 4-10x higher than the communication frequency. 3) Capture traffic during target operation. 4) In PulseView: Add Protocol Decoder (I2C/SPI/UART/1-Wire/CAN). 5) Decoder automatically parses protocol and shows human-readable data. Use case: captured I2C transaction shows EEPROM write of 'password123'. SPI decoder shows flash read of encryption key. UART decoder reveals boot log with filesystem layout."),
("How do you perform electromagnetic fault injection (EMFI)?","EMFI uses a tightly focused electromagnetic pulse to flip bits or disrupt CPU execution at a precise location. Unlike voltage glitching, EMFI can target specific silicon regions without circuit modification. DIY setup: 1) Build EM probe: coil of magnet wire (5-10 turns, ~5mm diameter) on ferrite core. 2) Drive coil with high-voltage pulse: MOSFET switch + 100V-400V capacitor bank triggered by microcontroller. 3) Connect trigger from target (GPIO or power trigger). 4) Mount probe on XY stage for precise positioning over IC. 5) Automate with ChipWhisperer EMFI module or custom Arduino controller. Professional tools: Langer EMV-Technik probes, Riscure VC Glitcher. Targeting: scan target IC surface systematically while glitching — monitor for faults in output (wrong calculation result, skipped instruction, premature return from security check). Best targets: boot ROM security checks, cryptographic function outputs, PIN comparison routines. Key paper: 'Fault Attacks on Secure Chips: From Theory to Practice' (CHES proceedings)."),
("How do you reverse engineer unknown serial protocols on hardware?","Systematic protocol RE workflow: 1) Capture raw data: logic analyzer on all data lines, capture during known operations (power on, button press, data transfer). 2) Visual analysis: look for patterns in PulseView — repeated bytes (sync/magic numbers), framing (start/stop bytes), periodic structure. 3) Frequency analysis: count byte values — 0x00 and 0xFF are common padding, frequently repeated bytes may be commands. 4) Correlation: press a button, observe what changes in the capture. Repeat for all buttons/functions. 5) Use URH (Universal Radio Hacker) for RF protocols or Scapy for network-like protocols. 6) Statistical analysis: measure packet length distribution, inter-packet timing. 7) Known protocol identification: use Sigrok protocol decoders, check against known industrial protocols (Modbus, DMX512, SMBus). 8) Differential analysis: compare captures for similar operations — what changes? Command byte shifts? Checksum updates? 9) Write custom protocol decoder in Sigrok Python."),
]

def write_dataset(path, qa_list, sys_msg):
    with open(path, "w") as f:
        for q, a in qa_list:
            entry = {"messages": [
                {"role": "system", "content": sys_msg},
                {"role": "user", "content": q},
                {"role": "assistant", "content": a}
            ]}
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
    print(f"Wrote {len(qa_list)} entries to {path}")

write_dataset(f"{OUT}/upgrade_osint_expanded.jsonl", OSINT_QA, SYS_TITAN)
write_dataset(f"{OUT}/upgrade_hardware_expanded.jsonl", HARDWARE_QA, SYS_TITAN)
print("Script 1 DONE")
